use rhwp::{DocumentCore, model::{paragraph::Paragraph, control::Control, shape::ShapeObject}};
#[derive(Default)]struct Counts{paras:usize,textboxes:usize,matches:usize}
fn shape(s:&ShapeObject,n:&mut Counts){
 if let Some(d)=s.drawing(){
  if let Some(tb)=&d.text_box{n.textboxes+=1;for p in &tb.paragraphs{if p.text.is_empty()&&p.stored_rows_include_hidden_guide()&&p.controls.iter().any(Control::is_treat_as_char_object){n.matches+=1;}}visit(&tb.paragraphs,n);}
  if let Some(c)=&d.caption{visit(&c.paragraphs,n);}
 }
 if let ShapeObject::Group(g)=s{if let Some(c)=&g.caption{visit(&c.paragraphs,n);}for c in &g.children{shape(c,n);}}
 if let ShapeObject::Picture(p)=s{if let Some(c)=&p.caption{visit(&c.paragraphs,n);}}
}
fn visit(ps:&[Paragraph],n:&mut Counts){for p in ps{n.paras+=1;for c in &p.controls{match c{
 Control::Table(t)=>{for c in &t.cells{visit(&c.paragraphs,n);}if let Some(c)=&t.caption{visit(&c.paragraphs,n);}},
 Control::Shape(s)=>shape(s,n),Control::Picture(p)=>if let Some(c)=&p.caption{visit(&c.paragraphs,n);},
 Control::Header(h)=>visit(&h.paragraphs,n),Control::Footer(h)=>visit(&h.paragraphs,n),Control::Footnote(h)=>visit(&h.paragraphs,n),Control::Endnote(h)=>visit(&h.paragraphs,n),Control::HiddenComment(h)=>visit(&h.paragraphs,n),Control::Field(f)=>visit(&f.memo_paragraphs,n),_=>{}
 }}}}
fn main(){for path in std::env::args().skip(1){let bytes=std::fs::read(&path).unwrap();let doc=DocumentCore::from_bytes(&bytes).unwrap();let mut n=Counts::default();for s in &doc.document().sections{visit(&s.paragraphs,&mut n);for m in &s.section_def.master_pages{visit(&m.paragraphs,&mut n);}}println!("{}\t{}\t{}\t{}",path,n.paras,n.textboxes,n.matches);}}
